go = a[-1] == 'go'
R = os.path.abspath(a[0]).rstrip('/')
def sha(t): return hashlib.sha256(t.encode('utf-8')).hexdigest()[:8]
F = json.loads(r"""{"assets/hair-words.js": {"base": "774c4e68", "new": "2922e18a", "A": [["    [/\\bth\u1ee3 nail\\b/gi, 'th\u1ee3 t\u00f3c'], [/\\bti\u1ec7m nail\\b/g, 'ti\u1ec7m t\u00f3c'], [/\\bTi\u1ec7m nail\\b/g, 'Ti\u1ec7m t\u00f3c'], [/\\bTh\u1ee3 nail\\b/g, 'Th\u1ee3 t\u00f3c'],", "    [/\\bTh\u1ee3 nail\\b/g, 'Th\u1ee3 t\u00f3c'], [/\\bth\u1ee3 nail\\b/gi, 'th\u1ee3 t\u00f3c'], [/\\bti\u1ec7m nail\\b/g, 'ti\u1ec7m t\u00f3c'], [/\\bTi\u1ec7m nail\\b/g, 'Ti\u1ec7m t\u00f3c'], /* hair-chu: 'Th\u1ee3' keeps its capital */"], ["    [/\\bnail design\\b/g, 'style'], [/\\bNail design\\b/g, 'Style'], [/\\bNails\\b/g, 'Hair'], [/\\bnails\\b/g, 'hair'],\n  ];", "    [/\\bnail designs\\b/g, 'styles'], [/\\bNail designs\\b/g, 'Styles'], [/\\bNail Design\\b/g, 'Style'], [/\\bNAIL DESIGN\\b/g, 'STYLE'],\n    [/\\bnail design\\b/g, 'style'], [/\\bNail design\\b/g, 'Style'], [/\\bNails\\b/g, 'Hair'], [/\\bnails\\b/g, 'hair'],\n    /* (hair-chu - LENH-HAIR-CHU, CHAT 03/11 20:42) the last nail words: polish / manicure / pedicure, the add-on choice, the turn line (no turns in a hair salon) */\n    [/(app |\u1ee9ng d\u1ee5ng )?\\bnail\\b(?! app)/g, (m, a) => (a ? m : 'hair')], [/\\bNail\\b(?! app)/g, 'Hair'], [/\\bNAIL\\b/g, 'HAIR'], [/\\bpolish\\b/g, 'color'], [/\\bPolish\\b/g, 'Color'], [/\\bPOLISH\\b/g, 'COLOR'],\n    [/\\bmanicures\\b/g, 'haircuts'], [/\\bmanicure\\b/g, 'haircut'], [/\\bManicures?\\b/g, 'Haircut'], [/\\bMANICURE\\b/g, 'HAIRCUT'],\n    [/\\bpedicures\\b/g, 'treatments'], [/\\bpedicure\\b/g, 'treatment'], [/\\bPedicures?\\b/g, 'Treatment'], [/\\bPEDICURE\\b/g, 'TREATMENT'],\n    [/with a hands service/g, 'with a hair service'], [/, the turn line,/g, ','],\n  ];"], ["    [/\\bTech\\b/g, 'Th\u1ee3 t\u00f3c'], [/\\btech\\b/g, 'th\u1ee3 t\u00f3c'], [/\\bNail [Ss]alon\\b/g, 'Ti\u1ec7m t\u00f3c'], [/\\bnail\\b/g, 't\u00f3c'], [/\\bNails\\b/g, 'T\u00f3c'],\n  ];", "    [/\\bTech\\b/g, 'Th\u1ee3 t\u00f3c'], [/\\btech\\b/g, 'th\u1ee3 t\u00f3c'], [/\\bNail [Ss]alon\\b/g, 'Ti\u1ec7m t\u00f3c'], [/(app |\u1ee9ng d\u1ee5ng )?\\bnail\\b/g, (m, a) => (a ? m : 't\u00f3c')], [/\\bNails\\b/g, 'T\u00f3c'], /* (hair-chu) 'app nail' (the nail app) stays */\n    [/\\bs\u01a1n m\u00f3ng\\b/g, 'nhu\u1ed9m'], [/\\bm\u00f3ng\\b/g, 't\u00f3c'],\n  ];"], ["    if (!s || !/[Tt]ech|TECH|[Nn]ail|NAIL|\ud83d\udc85|th\u1ee3|[Tt]\u00e9cnico/.test(s)) return s;", "    if (!s || !/[Tt]ech|TECH|[Nn]ail|NAIL|\ud83d\udc85|th\u1ee3|[Tt]\u00e9cnico|[Pp]olish|POLISH|anicure|ANICURE|edicure|EDICURE|hands service|turn line|m\u00f3ng/.test(s)) return s; /* (hair-chu) + the new words */"], ["    for (const a of ['placeholder', 'title', 'aria-label']) { const v = root.getAttribute && root.getAttribute(a); if (v) { const n = fix(v); if (n !== v) root.setAttribute(a, n); } }\n", "    for (const a of ['placeholder', 'title', 'aria-label']) { const v = root.getAttribute && root.getAttribute(a); if (v) { const n = fix(v); if (n !== v) root.setAttribute(a, n); } }\n    if (root.nodeName === 'OPTION' && HIDE_OPT.test(root.textContent.trim())) { root.hidden = true; root.disabled = true; } /* (hair-chu) no turn line in a hair salon */\n"], ["  const go = () => { walk(document.body);", "  /* (hair-chu) no Turns in a hair salon: the stylist app's 'Turn' box, the front desk's 'Turn view', the Check-in 'Turns' button */\n  const HIDE_OPT = /^(Turn line moved by hand|Turn line reset)$/;\n  const css = () => { if (document.getElementById('hairChuCss')) return; const st = document.createElement('style'); st.id = 'hairChuCss'; st.textContent = '#tvTurn,#dkTvB,#ckTurns{display:none!important}'; (document.head || document.documentElement).appendChild(st); };\n  const go = () => { css(); walk(document.body);"], ["if (m.type === 'characterData') walk(m.target); else m.addedNodes.forEach(walk); }", "if (m.type === 'characterData') walk(m.target); else if (m.type === 'attributes') { const v = m.target.getAttribute(m.attributeName); if (v) { const n = fix(v); if (n !== v) m.target.setAttribute(m.attributeName, n); } } /* (hair-chu) words put in a title / label later (desk-lang) */ else m.addedNodes.forEach(walk); }"], ["mo.observe(document.body, { childList: true, subtree: true, characterData: true });", "mo.observe(document.body, { childList: true, subtree: true, characterData: true, attributes: true, attributeFilter: ['placeholder', 'title', 'aria-label'] }); /* hair-chu */"], ["    if (root.nodeType !== 1 || SKIP[root.nodeName]) return;\n", "    if (root.nodeType === 1 && (root.nodeName === 'INPUT' || root.nodeName === 'TEXTAREA')) { for (const a of ['placeholder', 'title', 'aria-label']) { const v = root.getAttribute(a); if (v) { const n = fix(v); if (n !== v) root.setAttribute(a, n); } } return; } /* hair-chu: a box's label / hint, never what is typed */\n    if (root.nodeType !== 1 || SKIP[root.nodeName]) return;\n"]]}, "inc/api/_texts.php": {"base": "b50dc39a", "new": "14e2597a", "A": [["'sms_design_confirm' => ['Line: nail design (confirmation)', 'D\u00f2ng th\u00eam: c\u00f3 design (x\u00e1c nh\u1eadn)', 'Added to the confirmation when a nail design was chosen',", "'sms_design_confirm' => ['Line: style photo (confirmation)', 'D\u00f2ng th\u00eam: c\u00f3 ki\u1ec3u t\u00f3c (x\u00e1c nh\u1eadn)', 'Added to the confirmation when a style was chosen' /* hair-chu */,"], ["'sms_design_reminder' => ['Line: nail design (reminder)', 'D\u00f2ng th\u00eam: c\u00f3 design (nh\u1eafc l\u1ecbch)', 'Added to the reminder when a nail design was chosen',", "'sms_design_reminder' => ['Line: style photo (reminder)', 'D\u00f2ng th\u00eam: c\u00f3 ki\u1ec3u t\u00f3c (nh\u1eafc l\u1ecbch)', 'Added to the reminder when a style was chosen' /* hair-chu */,"]]}, "inc/core/settings.php": {"base": "6997fa9a", "new": "29227b3d", "A": [["        'sms_design_confirm' => \"\ud83d\udc85 You chose a nail design \u2014 please reply to this text with a photo of the design you'd like, so your tech can get ready!\",\n        'sms_design_reminder' => \"Don't forget to send us a photo of your design \ud83d\udc85\",\n", "        /* (hair-chu) the hair salon's words */\n        'sms_design_confirm' => \"\u2702\ufe0f You chose a style \u2014 please reply to this text with a photo of the look you'd like, so your stylist can get ready!\",\n        'sms_design_reminder' => \"Don't forget to send us a photo of the look you'd like \u2702\ufe0f\",\n"]]}, "inc/core/sms.php": {"base": "32eec464", "new": "b2b78d05", "A": [["        $p = str_replace(['\ud83d\udc85', 'Cualquier t\u00e9cnico disponible',", "        $p = preg_replace(['/\\bnail designs?\\b/', '/\\bNail [Dd]esigns?\\b/', '/\\bpolish\\b/', '/\\bPolish\\b/'], ['style', 'Style', 'color', 'Color'], $p); /* (hair-chu) a text already saved with the nail words */\n        $p = str_replace(['\ud83d\udc85', 'Cualquier t\u00e9cnico disponible',"]]}}""")
if not os.path.isfile(R + '/inc/hair.php') or not os.path.isfile(R + '/assets/hair-words.js'): sys.exit('STOP: ' + R + ' is not the hair app dir (no inc/hair.php / assets/hair-words.js) - nothing changed')
if not os.path.isfile(R + '/assets/hair-ui.js'): sys.exit('STOP: fixHAIR-ui is not in ' + R + ' yet (this package comes after it) - nothing changed')
plan = []; bad = 0
for f, x in F.items():
    p = R + '/' + f
    if not os.path.isfile(p): print(f, 'MISSING'); bad = 1; continue
    s = open(p, encoding='utf-8').read(); n = [s.count(o) for o, _ in x['A']]; al = 'hair-chu' in s
    print(f, 'sha', sha(s), '(LAMWEB base', x['base'] + ')', 'anchors', *n, 'already', al)
    if al or n != [1] * len(n): bad = 1; continue
    t = s
    for o, nn in x['A']: t = t.replace(o, nn)
    plan.append((f, p, t))
if bad: sys.exit('STOP: an anchor is not found exactly once or already patched - nothing changed')
if not go:
    for f, p, t in plan: print('NEW would be', f, sha(t))
    sys.exit('check only - run again with: go')
bk = R + '/inc/old-hairchu-' + time.strftime('%m%d%H%M%S'); os.makedirs(bk); done = []
def back(msg):
    for q, bb in done: shutil.copy2(bb, q)
    sys.exit('ERROR ' + msg + ' - every file put back (backups in ' + bk + ')')
for f, p, t in plan:
    b = bk + '/' + f.replace('/', '__') + '.pre-hairchu'; shutil.copy2(p, b); m = os.stat(p).st_mode
    open(p, 'w', encoding='utf-8').write(t); os.chmod(p, m); done.append((p, b))
    c = ['php', '-l', p] if p.endswith('.php') else (['node', '--check', p] if shutil.which('node') else None)
    if c:
        r = subprocess.run(c, capture_output=True, text=True)
        if r.returncode: back('in ' + p + ': ' + (r.stdout + r.stderr)[:300])
    print('NEW', f, sha(t), 'backup', b)
print('OK hair-chu: the last nail words -> hair words (hair-words.js, SMS texts, SMS templates), no Turn box / Turn view / turn line. Backups: ' + bk + '. Reload the pages.')
